    for r, row in enumerate(grid):
        xs = [c for c, v in enumerate(row) if v == fg]
        if not xs:
            continue

        # Find the rightmost solid foreground run of length at least two.
        runs = []
        i = 0
        while i < len(xs):
            a = b = xs[i]
            i += 1
            while i < len(xs) and xs[i] == b + 1:
                b = xs[i]
                i += 1
            if b - a + 1 >= 2:
                runs.append((a, b))
        if not runs:
            continue
        a, b = runs[-1]

        # A regular sequence of isolated marks to the left indicates
        # continuation at that same spacing beyond the bar.
        left = [x for x in xs if x < a]
        if len(left) >= 3:
            gaps = [y - x for x, y in zip(left, left[1:])]
            if len(set(gaps)) == 1 and gaps[0] > 1:
                step = gaps[0]
                x = b + step - ((b + step - left[-1]) % step)
                if x <= b:
                    x += step
                while x < w:
                    if row[x] == bg:
                        out[r][x] = 1
                    x += step
                continue

        # Otherwise repeat the final small run-cluster pattern, when
        # there are equal-length clusters with a regular gap.
        tail_runs = []
        for x in xs:
            if not tail_runs or x > tail_runs[-1][-1] + 1:
                tail_runs.append([x])
            else:
                tail_runs[-1].append(x)
        if len(tail_runs) >= 3:
            sizes = [len(q) for q in tail_runs[-3:]]
            starts = [q[0] for q in tail_runs[-3:]]
            periods = [starts[i+1] - starts[i] for i in range(2)]
            if sizes[1] == sizes[2] and periods[0] == periods[1]:
                period = periods[1]
                start = starts[-1] + period
                while start < w:
                    for k in range(sizes[-1]):
                        x = start + k
                        if x < w and row[x] == bg:
                            out[r][x] = 1
